bool :>> signalCondition {
			doc
			/*
			 * The Boolean condition of the currentTime of the signalClock being
			 * equal to the signalTime.
			 */

			signalClock.currentTime == signalTime
		}

in bool redefines ifTest {
				not changeSignal.signalCondition()
			}

